  it('bypasses onError when a non-Error is thrown, but still propagates it', async () => {
    let onErrorCalled = false;
    const hooks: OrchestratorHooks = {
      onError: async () => {
        onErrorCalled = true;
      },
    };

    const nonErrorProvider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw 'not an Error object'; // eslint-disable-line @typescript-eslint/no-throw-literal
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(nonErrorProvider, promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toBe('not an Error object');
    expect(onErrorCalled).toBe(false);
  });
});

