const TRAILING_LINK_PARENTHETICAL = /^\(\[[^\]]*\]\(/;
function indexOfNextNonSpace(text, from) {
    let index = from;
    while (index < text.length && text[index] === " ") {
        index++;
    }
    return index;
}
function pushTrimmedNonEmpty(out, text) {
    const trimmed = text.trim();
    if (trimmed) {
