    }
}
function endsInAbbreviationOrInitial(buf) {
    const trimmed = buf.trimEnd().replace(/[.?!]+$/, "");
    const lastWord = trimmed.split(/\s+/).pop() || "";
    if (ABBREVIATIONS.has(lastWord)) {
        return true;
    }
    return /^[A-Z]$/.test(lastWord);
}
